#include "Messenger_i.h"
#include "ace/OS_NS_time.h"
#include <iostream>

CORBA::Boolean
Messenger_i::send_message (char const *user_name,
                           char const *subject,
                           char *&message)
{
  std::cerr << "Message from: " << user_name << std::endl;
  std::cerr << "Subject:      " << subject << std::endl;
  std::cerr << "Message:      " << message << std::endl;
  return true;
}

char *Messenger_i::get_time ()
{
  time_t current_time {};
  ACE_OS::time (&current_time);
  struct tm time_info {};
  if (ACE_OS::localtime_r (&current_time, &time_info) == nullptr)
    {
      throw CORBA::INTERNAL ();
    }

  char time_string[26] {};
  if (ACE_OS::asctime_r (&time_info, time_string, sizeof (time_string)) == nullptr)
    {
      throw CORBA::INTERNAL ();
    }
  return CORBA::string_dup (time_string);
}
